-- Venue Live Guest "Wedding Wabi Sabi". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara wabisabi), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'wabisabi', 'Wedding Wabi Sabi', 'wabisabi', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 143, 'center 38%',
  $t${"name":"Wabi Sabi","orn":"diamond","ui":{"ivory":"#F6F0E2","white":"#FFFFFF","soft":"#E6DDC6","soft2":"#B88A52","accent":"#7A8456","deep":"#3E3A28","ink":"#3E3A28","mute":"#8A8468","line":"#DDD3B8","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#F4EBD6","ink":"#3E3A28","accent":"#7A8456","gold":"#B88A52","leaf":"#E6DDC6","hbg":"rgba(246,240,226,.94)","hline":"#B88A52","motif":"diamond"},"hud":{"bg":"rgba(62,58,40,.9)","acc":"#E8C99A","on":"#3E3A28"},"scr":{"wine":"#3E3A28","veil":"246,240,226"}}$t$::jsonb
